mapper.select:
/** pchSql - selectProjectCodeList - 과제별 기여율 - 과제코드 조회 */ SELECT B.VESTICODE as "vEstiCode" /* 평가코드 */ , B.VPROJECTCODE as "vProjectCode" /* 과제코드 */ , B.VPROJECTNAME as "vProjectName" /* 과제명 */ , B.VPROJECTPM as "vProjectPm" /* 과제PM */ , ( SELECT VNAME FROM TAA2101 WHERE VEMPLNO = B.VPROJECTPM ) as "vProjectPmName" /* 과제PM명 */ , ( SELECT NVL(SUM(NCONTRIBUTION), 0) SUM FROM TCA4005 WHERE VESTICODE = #{vEstiCode} AND VPROJECTCODE = B.VPROJECTCODE ) as "vProjectSum" /* 기여율합 */ , B.VESTISTEP as "vEstiStep" /* 진행단계 */ , ( SELECT DECODE(INSTR(SUBSTR(XMLAGG(XMLELEMENT(A, NVL(A.VCONFIRM, 'N'))).EXTRACT('//text()'),1), 'N'), 0, 'Y', 'N') FROM TCA4005 A WHERE A.VESTICODE = B.VESTICODE AND A.VPROJECTCODE = B.VPROJECTCODE ) as "vConfirm" /* 확인여부 */ , ( SELECT DECODE(INSTR(SUBSTR(XMLAGG(XMLELEMENT(A, NVL(A.VFINISH, 'N'))).EXTRACT('//text()'),1), 'N'), 0, 'Y', 'N') FROM TCA4005 A WHERE A.VESTICODE = B.VESTICODE AND A.VPROJECTCODE = B.VPROJECTCODE ) as "vFinish" /* 완료여부 */ FROM TCA4003 B
B.VESTICODE = #{vEstiCode}
AND B.VESTISTEP = #{vEstiStep}
ORDER BY B.VESTICODE, B.VPROJECTCODE

/** pchSql - selectProjectContributeList - 과제별/개인별 기여율 조회 */ SELECT A.VESTICODE as "vEstiCode" /* 01_평가코드 */ , A.VPROJECTCODE as "vProjectCode" /* 02_과제코드 */ , A.VEMPLNO as "vEmplNo" /* 03_사번 */ , B.VNAME as "vName" /* 04_성명 */ , B.VPOSNAME as "vPosName" /* 05_직위명 */ , A.VWORK as "vWork" /* 06_업무 */ , A.NCONTRIBUTION as "nContribution" /* 07_기여율 */ , A.VCONTENT as "vContent" /* 08_평가의견 */ , A.VCONFIRM as "vConfirm" /* 09_확인여부 */ , A.VFINISH as "vFinish" /* 09_완료여부 */ FROM TCA4005 A, TCA4002 B
AND A.VESTICODE = #{vEstiCode} AND A.VPROJECTCODE = #{vProjectCode} AND A.VESTICODE = B.VESTICODE AND A.VEMPLNO = B.VEMPLNO
ORDER BY B.VNAME

mapper.update:
/** pchSql - updateContribution - 과제별 기여율 수정 */
UPDATE
   TCA4005

    VWORK = #{vWork}                , 
    NCONTRIBUTION = #{nContribution}, 
    VCONTENT = #{vContent}          , 
   
           VCONFIRM = ''                   , 
      
          VCONFIRM = #{vConfirm}          , 
      
   
   
            VFINISH = ''                    , 
      
          VFINISH = #{vFinish}            , 
      
   


       VESTICODE = #{vEstiCode}
   AND VPROJECTCODE = #{vProjectCode}
   AND VEMPLNO = #{vEmplNo}

mapper.select:
/** pchSql - selectEmplNoList - 관리자 > 개인별 기여율관리 - 참여연구원 목록 조회 */ SELECT A.VESTICODE as "vEstiCode" /* 평가연도 */ , A.VEMPLNO as "vEmplNo" /* 사번 */ , A.VNAME as "vName" /* 성명 */ , A.VPOSNAME as "vPosName" /* 직위명 */ , A.VDEPTNAME as "vDeptName" /* 부서명 */ , A.VTEAMNAME as "vTeamName" /* 팀명 */ , ( SELECT NVL(SUM(NVL(B.NCONTRIBUTION, 0)), 0) FROM TCA4005 B WHERE A.VESTICODE = B.VESTICODE AND A.VEMPLNO = B.VEMPLNO ) as "nContribution" /* 개인 기여율 합 */ FROM TCA4002 A
A.VESTICODE = #{vEstiCode} AND A.VESTIYN = 'Y'
ORDER BY A.VESTICODE, A.VNAME

/** pchSql - selectEmplNoContributeList - 관리자 > 개인별 기여율관리 - 개인별 기여율 목록 조회 */ SELECT A.VESTICODE as "vEstiCode" /* 01_평가코드 */ , A.VPROJECTCODE as "vProjectCode" /* 02_과제코드 */ , B.VPROJECTNAME as "vProjectName" /* 03_과제명 */ , B.VPROJECTPM as "vProjectPm" /* 04_과제PM */ , C.VNAME as "vProjectPmName" /* 04_과제PM명 */ , A.VEMPLNO as "vEmplNo" /* 04_사번 */ , A.VWORK as "vWork" /* 05_업무 */ , A.NCONTRIBUTION as "nContribution" /* 06_기여율 */ , A.VCONTENT as "vContent" /* 07_평가의견 */ , A.VCONFIRM as "vConfirm" /* 08_확인여부 */ , A.VFINISH as "vFinish" /* 09_완료여부 */ FROM TCA4005 A, TCA4003 B, TCA4002 C
A.VESTICODE = B.VESTICODE AND A.VPROJECTCODE = B.VPROJECTCODE AND B.VPROJECTPM = C.VEMPLNO AND A.VESTICODE = #{vEstiCode} AND A.VEMPLNO = #{vEmplNo} AND C.VESTICODE = #{vEstiCode}
ORDER BY B.VPROJECTCODE

/** pchSql - selectPhcProjectCodeList - 과제별 인원관리 - 과제코드 목록 조회 */ SELECT A.VESTICODE as "vEstiCode" /* 01_평가코드 */ , A.VPROJECTCODE as "vProjectCode" /* 02_과제코드 */ , A.VPROJECTNAME as "vProjectName" /* 03_과제명 */ , A.VPROJECTPM as "vProjectPm" /* 04_과제PM */ , B.VNAME as "vProjectPmName" /* 05_과제PM명 */ , A.VPROJECTEVA as "vProjectEva" /* 06_과제평가자 */ , C.VNAME as "vProjectEvaName" /* 07_과제평가자명 */ FROM TCA4003 A, TAA2101 B, TAA2101 C
A.VESTICODE = #{vEstiCode} AND A.VPROJECTPM = B.VEMPLNO(+) AND A.VPROJECTEVA = C.VEMPLNO(+)
ORDER BY A.VPROJECTCODE

/** pchSql - selectPhcEmpList - 과제별 인원관리 - 과제 참여연구원 목록 조회 */ SELECT A.VESTICODE as "vEstiCode" /* 01_평가코드 */ , A.VPROJECTCODE as "vProjectCode" /* 02_과제코드 */ , A.VEMPLNO as "vEmplNo" /* 03_사번 */ , B.VNAME as "vName" /* 05_성명 */ , B.VPOSNAME as "vPosName" /* 05_직위명 */ , B.VTEAMNAME as "vTeamName" /* 05_팀명 */ FROM TCA4005 A, TCA4002 B
A.VESTICODE = #{vEstiCode} AND A.VPROJECTCODE = #{vProjectCode} AND A.VESTICODE = B.VESTICODE AND A.VEMPLNO = B.VEMPLNO(+) AND B.VESTIYN = 'Y'
ORDER BY B.VNAME

mapper.delete:
/** pcaSql - deletePhcEmplNo - 과제별 인원관리 - 과제 참여연구원 삭제 */
DELETE FROM TCA4005

       VESTICODE = #{vEstiCode}
   AND VPROJECTCODE = #{vProjectCode}
   AND VEMPLNO = #{vEmplNo}
